import bcrypt from 'bcrypt';

/**
 * Hash the given password securely and return the hash as a string.
 *
 * @param {string} password - The password to be hashed.
 * @returns {Promise<string>} The securely hashed password.
 */
async function get_password_hash(password) {
  // The number of salt rounds is a trade-off between security and performance.
  // A higher number of rounds increases security but also increases the time
  // it takes to hash the password, which can impact performance on high-volume systems.
  // For most applications, 10-12 rounds is a good balance.
  // For extremely high-volume systems, consider a lower number of rounds or
  // a more performant hashing algorithm if bcrypt proves to be a bottleneck,
  // ensuring security is not compromised.
  // To mitigate potential denial-of-service attacks through resource exhaustion
  // with very high salt rounds, we can consider a dynamic approach or rate limiting
  // at the application level. For this function, we'll stick to a reasonable
  // fixed number of rounds that balances security and performance for typical use cases.
  const saltRounds = 12;
  const hash = await bcrypt.hash(password, saltRounds);
  return hash;
}
